11	#include "ascir/Dialect/Asc/IR/Asc.h"
12	#include "ascir/Dialect/Asc/Transforms/Passes.h"
13	#include "ascir/Dialect/Asc/Utils/Utils.h"
14	
15	#include "mlir/Dialect/Func/IR/FuncOps.h"
16	#include "mlir/Dialect/SCF/IR/SCF.h"
17	#include "mlir/IR/Builders.h"
18	#include "mlir/IR/Dominance.h"
19	#include "mlir/Support/LLVM.h"
20	#include "mlir/Transforms/GreedyPatternRewriteDriver.h"
21	
22	namespace mlir {
23	namespace ascendc {
24	#define GEN_PASS_DEF_INSERTSYNC
25	#include "ascir/Dialect/Asc/Transforms/Passes.h.inc"
26	} // namespace ascendc
27	} // namespace mlir
28	
29	using namespace mlir;
30	
31	namespace {
32	
33	Value findQueue(Value tensor)
34	{
35	    if (auto op = tensor.getDefiningOp<ascendc::TQueBindAllocTensorOp>()) {
36	        return op.getQueue();
37	    }
38	    if (auto op = tensor.getDefiningOp<ascendc::TQueBindDequeTensorOp>()) {
39	        return op.getQueue();
40	    }
41	    return nullptr;
42	}
43	
44	void enqueueTensors(func::FuncOp funcOp)
45	{
46	    funcOp.walk([](ascendc::OpWithDst op) {
47	        auto tensor = op.getDst();
48	        if (!tensor || !isa<ascendc::BaseTensorType>(tensor.getType()) ||
49	            isa_and_present<ascendc::GlobalTensorOp>(tensor.getDefiningOp()))
50	            return;
51	        OpBuilder builder(op.getContext());
52	        builder.setInsertionPointAfter(op);
53	        if (auto queue = findQueue(tensor)) {
54	            builder.create<ascendc::TQueBindEnqueTensorOp>(op.getLoc(), queue, tensor);
55	            return;
56	        }
57	        builder.create<ascendc::PipeBarrierOp>(op.getLoc(), ascendc::Pipe::PIPE_V);
58	    });
59	}
60	
61	void createSetGetValueSync(bool isBefore, OpBuilder& builder, Location loc)
62	{
63	    ascendc::HardEvent currentEvent = isBefore ? ascendc::HardEvent::V_S : ascendc::HardEvent::S_V;
64	    Value pipe = builder.create<ascendc::PipeOp>(loc);
65	    auto eventId =
66	        builder.create<ascendc::TPipeFetchEventIDOp>(loc, builder.getI8Type(), pipe, currentEvent).getResult();
67	    builder.create<ascendc::SetFlagOp>(loc, currentEvent, eventId);
68	    builder.create<ascendc::WaitFlagOp>(loc, currentEvent, eventId);
69	}
70	
71	void syncGetValueOp(func::FuncOp& funcOp)
72	{
73	    funcOp.walk([](ascendc::APIOp op) {
74	        if (isa<ascendc::LocalTensorGetValueOp, ascendc::GlobalTensorGetValueOp>(op)) {
75	            auto loc = op.getLoc();
76	            OpBuilder builder(op);
77	            createSetGetValueSync(true, builder, loc);
78	            builder.setInsertionPointAfter(op);
79	            createSetGetValueSync(false, builder, loc);
80	        }
81	    });
82	}
83	
84	void syncSetValueOp(func::FuncOp& funcOp)
85	{
86	    funcOp.walk([](ascendc::APIOp op) {
87	        if (isa<ascendc::LocalTensorSetValueOp, ascendc::GlobalTensorSetValueOp>(op)) {
88	            auto loc = op.getLoc();
89	            OpBuilder builder(op);
90	            if (auto forOp = op->getParentOfType<scf::ForOp>()) {
91	                constexpr unsigned oneOpOneYield = 2U;
92	                if (forOp.getBody()->getOperations().size() == oneOpOneYield) {
93	                    builder.setInsertionPoint(forOp);
94	                    createSetGetValueSync(true, builder, loc);
95	                    builder.setInsertionPointAfter(forOp);
96	                    createSetGetValueSync(false, builder, loc);
97	                    return;
98	                }
99	            }
100	            createSetGetValueSync(true, builder, loc);
101	            builder.setInsertionPointAfter(op);
102	            createSetGetValueSync(false, builder, loc);
103	        }
104	    });
105	}
106	
107	bool reEnque(OpBuilder& b, Location loc, ascendc::TQueBindEnqueTensorOp enq, ascendc::TQueBindDequeTensorOp deq)
108	{
109	    DominanceInfo di;
110	    if (!di.dominates(enq, deq)) {
111	        auto* enqParent = deq->getParentRegion()->findAncestorOpInRegion(*enq);
112	        if (!enqParent) {
113	            enq.emitOpError("failed to be hoisted to tensor deque op scope");
114	            return false;
115	        }
116	        b.setInsertionPointAfter(enqParent);
117	        b.create<ascendc::TQueBindEnqueTensorOp>(loc, enq.getQueue(), enq.getTensor());
118	        enq.erase();
119	    }
120	    return true;
121	}
122	
123	bool dequeueTensors(Region& region)
124	{
125	    DominanceInfo di;
126	    bool res = true;
127	    for (Block& block : region) {
128	        for (Operation& op : llvm::make_early_inc_range(block)) {
129	            auto enq = dyn_cast<ascendc::TQueBindEnqueTensorOp>(op);
130	            if (!enq) {
131	                for (Region& inner : op.getRegions()) {
132	                    res &= dequeueTensors(inner);
133	                }
134	                continue;
135	            }
136	            auto tensor = enq.getTensor();
137	            std::vector<Operation*> users;
138	            llvm::copy_if(tensor.getUsers(), std::back_inserter(users), [&](Operation* user) {
139	                return !isa<ascendc::TQueBindFreeTensorOp>(user) && ascendc::opPrecedes(enq, user, di);
140	            });
141	            if (users.empty()) {
142	                continue;
143	            }
144	            Operation* firstUser = *std::min_element(users.begin(), users.end(), [&](Operation* lhs, Operation* rhs) {
145	                return ascendc::opPrecedes(lhs, rhs, di);
146	            });
147	            auto* userInSameRegion = enq->getParentRegion()->findAncestorOpInRegion(*firstUser);
148	            if (userInSameRegion) {
149	                firstUser = userInSameRegion;
150	            }
151	            OpBuilder builder(firstUser);
152	            auto deq = builder.create<ascendc::TQueBindDequeTensorOp>(enq.getLoc(), tensor.getType(), enq.getQueue());
153	            if (!reEnque(builder, op.getLoc(), enq, deq)) {
154	                return false;
155	            }
156	            tensor.replaceUsesWithIf(deq.getTensor(), [&](OpOperand& opnd) {
157	                auto* owner = opnd.getOwner();
158	                return llvm::is_contained(users, owner);
159	            });
160	        }
161	    }
162	    return res;
163	}
164	
165	void canonicalizeBarriers(func::FuncOp funcOp)
166	{
167	    auto builder = OpBuilder::atBlockTerminator(&funcOp.getFunctionBody().back());
168	    builder.create<ascendc::PipeBarrierOp>(builder.getUnknownLoc(), ascendc::Pipe::PIPE_ALL);
169	    RewritePatternSet patterns(funcOp.getContext());
170	    ascendc::PipeBarrierOp::getCanonicalizationPatterns(patterns, funcOp.getContext());
171	    (void)applyPatternsAndFoldGreedily(funcOp, std::move(patterns));
172	}
173	
174	struct InsertSyncPass : public ascendc::impl::InsertSyncBase<InsertSyncPass> {
175	public:
176	    void runOnOperation() override
177	    {
178	        func::FuncOp funcOp = getOperation();
179	        if (funcOp.isDeclaration()) {
180	            return;
181	        }
182	        enqueueTensors(funcOp);
183	        if (!dequeueTensors(funcOp.getRegion())) {
184	            signalPassFailure();
185	            return;
186	        }
187	        syncGetValueOp(funcOp);
188	        syncSetValueOp(funcOp);
189	        canonicalizeBarriers(funcOp);
190	    }
191	};
192	
193	} // namespace
194	
195	namespace mlir {
196	namespace ascendc {
197	std::unique_ptr<Pass> createInsertSyncPass() { return std::make_unique<InsertSyncPass>(); }
198	} // namespace ascendc
199	} // namespace mlir
