38	        if (funcOp.isDeclaration()) {
39	            return;
40	        }
41	        ValueMap<Value> allocTensors; // maps queue to allocated tensor
42	        funcOp.walk(
43	            [&allocTensors](ascendc::TQueBindAllocTensorOp op) { allocTensors[op.getQueue()] = op.getTensor(); });
44	        funcOp.walk([this, &allocTensors](ascendc::TQueBindDequeTensorOp op) {
45	            auto it = allocTensors.find(op.getQueue());
46	            if (it == allocTensors.end()) {
47	                op.emitOpError("doesn't have corresponding alloc_tensor op");
48	                signalPassFailure();
49	                return;
50	            }
51	            op.replaceAllUsesWith(it->second);
52	            op.erase();
53	        });
54	        eraseOps<ascendc::TQueBindEnqueTensorOp>(funcOp);
55	        eraseOps<ascendc::SetFlagOp>(funcOp);
56	        eraseOps<ascendc::WaitFlagOp>(funcOp);
57	        eraseOps<ascendc::PipeBarrierOp>(funcOp);
58	    }
59	};
60	
61	} // namespace
62	
63	namespace mlir {
