34	        RewritePatternSet patterns(context);
35	        patterns.add<
36	            //
37	            ascendc::HoistOpPattern<ascendc::QueueOp>, ascendc::HoistOpPattern<ascendc::QueBindOp>,
38	            ascendc::HoistOpPattern<ascendc::TBufOp>, ascendc::HoistOpPattern<ascendc::TPipeInitBufferOp>,
39	            ascendc::HoistOpPattern<ascendc::TPipeInitQueueOp>, ascendc::HoistOpPattern<ascendc::TBufGetTensorOp>
40	            //
41	            >(context);
42	        if (applyPatternsAndFoldGreedily(getOperation(), std::move(patterns)).failed()) {
43	            signalPassFailure();
44	        }
45	    }
46	};
